public static boolean isEqual(BinNode<Integer> t1, BinNode<Integer> t2) {
    if (t1 == null && t2 == null) {
        return true;
    }
    if (t1 == null || t2 == null) {
        return false;
    }
    return t1.getValue().equals(t2.getValue()) && isEqual(t1.getLeft(), t2.getLeft()) && isEqual(t1.getRight(), t2.getRight());
}

public static void mirror(BinNode<Integer> t) {
    if (t == null) {
        return;
    }
    BinNode<Integer> temp = t.getLeft();
    t.setLeft(t.getRight());
    t.setRight(temp);
    mirror(t.getLeft());
    mirror(t.getRight());
}

