public static String treeText(BinNode<Integer> t) {
    if (t == null) {
        return "-";
    }
    if (!t.hasLeft() && !t.hasRight()) {
        return "" + t.getValue();
    }
    return t.getValue() + "(" + treeText(t.getLeft()) + "," + treeText(t.getRight()) + ")";
}

